entries[184937] = { ["name"] = "Chronoboon Displacer", ["text"] = "Use: Alters the fabric of time, suspending beneficial world effects from dragonslaying, Dire Maul, Zul'Gurub, and Felwood. (1 Hour Cooldown)\nSell Price:" }
entries[184938] = { ["name"] = "Supercharged Chronoboon Displacer", ["text"] = "Binds when picked up\nUnique\nUse: Restores your suspended world effects." }
