entries[190186] = { ["name"] = "Wooden Figurine", ["text"] = "Quest Item\nUnique\nUse: Call forth an incubus using the summoning circle. (3 Min Cooldown)\n\"An inscription on the base reads: I'm home.\"" }
entries[190187] = { ["name"] = "Withered Scarf", ["text"] = "Quest Item\nUnique\nUse: Call forth an incubus using the summoning circle. (3 Min Cooldown)\n\"Delicate patterns are embroidered into the cloth, along with the letters 'M+K'.\"" }
