entries[190307] = { ["name"] = "Unlit Torch", ["text"] = "Conjured Item\nQuest Item\nUnique\n\"You know what would look really good on this torch? Fire.\"" }
entries[190308] = { ["name"] = "Burning Torch", ["text"] = "Conjured Item\nQuest Item\nUnique\nDuration: 5 min\nUse: Tosses a torch at the target location, starting a fire.\n\"Useful for fiery distractions!\"" }
entries[190309] = { ["name"] = "Wooden Figurine", ["text"] = "Quest Item\nUnique\n\"An inscription on the base reads: I'm home.\"" }
entries[191204] = { ["name"] = "Lesser Deathstone", ["text"] = "Binds when picked up\nUse: Turn 100 lesser deathstones into a greater one." }
entries[191249] = { ["name"] = "Greater Deathstone", ["text"] = "Binds when picked up\n\"A vibrant green stone glowing with untold energies.\"" }
entries[191267] = { ["name"] = "Rune of Teleportation: Antechamber", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Transports you to the Antechamber in Naxxramas." }
entries[191268] = { ["name"] = "Orb of Corruption", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Crush the orb, increasing the amount of lesser deathstones absorbed from Kel'Thuzad's minions by 50% for 30 min." }
entries[191272] = { ["name"] = "Rod of Necromancy", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Subdues the will of an undead target within Naxxramas, causing them to become charmed for 5 min.\n3 Charges" }
entries[191280] = { ["name"] = "Fungal Spore Cluster", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Grants your offensive abilities a chance to summon a spore that affects nearby players with Fungal Bloom when killed. This effect lasts for 1 hour.\n\nFungal Bloom\nInflicts 150 Nature damage every 1 sec while increasing the chance for a melee, ranged, or spell critical by 15%. (Proc chance: 10%, 15s cooldown)" }
entries[191288] = { ["name"] = "Rune of Teleportation: Frostwyrm's Lair", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Transports you to Frostwyrm's Lair in Naxxramas." }
entries[191292] = { ["name"] = "Ritual Dagger", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Absorb the life force of those around you, increasing stamina by 3 for each target hit. This effect stacks up to 40 and lasts for 1 hour." }
entries[191312] = { ["name"] = "Failsafe Phylactery", ["text"] = "Binds when picked up\nUnique\nDuration: 7 daysTrinket\nRequires Level 60\nEquip: Prevents an attack that would otherwise kill you. Triggering this effect also grants you 3 sec of damage immunity and shatters the phylactery." }
entries[191313] = { ["name"] = "Mask of Death", ["text"] = "Duration: 7 days\nUse: Adopt the visage of a denizen of Naxxramas." }
entries[191414] = { ["name"] = "Skeletal Artifact", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Entraps the soul of the dead target, granting you a beneficial effect. This effect lasts for 1 hour." }
entries[191458] = { ["name"] = "Shattered Phylactery", ["text"] = "Binds when picked up\nUnique\nDuration: 7 daysTrinket\nRequires Level 60\n\"Dull and useless.\"" }
entries[191459] = { ["name"] = "Rune of Fortune", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Empowers Kel'Thuzad and his lieutenants with necromantic energy, granting them increased health and damage. Empowered foes will yield additional rewards upon defeat.\n\nThis effect stacks and lasts for an entire week." }
entries[191477] = { ["name"] = "Skeletal Hitching Post", ["text"] = "Binds when picked up\nUnique\nDuration: 7 days\nRequires Level 60\n\nUse: Summons a skeletal hitching post.\n\nParty members may use the post to acquire a Skeletal Steed." }
entries[191480] = { ["name"] = "Skeletal Steed", ["text"] = "Binds when picked up\nUnique\nDuration: 1 hour\nMount\nRequires Level 40\n\nUse: Summons and dismisses a skeletal steed. This steed is obedient to the summoner and can be used as a mount within Naxxramas. Any hostile action towards the rider forces the steed to run away in fear. (3 Sec Cooldown)" }
entries[191481] = { ["name"] = "Tabard of Mastery", ["text"] = "Binds when picked up\nTabard\n\"A testament to mastery.\"" }
entries[191550] = { ["name"] = "Book of Deathstones: Mask of Death", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a mask of death.\"" }
entries[191605] = { ["name"] = "Book of Deathstones: Rune of Teleportation I", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a rune of teleportation.\"" }
entries[191606] = { ["name"] = "Book of Deathstones: Orb of Corruption", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into an orb of corruption.\"" }
entries[191607] = { ["name"] = "Book of Deathstones: Skeletal Artifact", ["text"] = "Binds when picked up\nUnique\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a skeletal artifact.\"" }
entries[191608] = { ["name"] = "Book of Deathstones: Rod of Necromancy", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a rod of necromancy.\"" }
entries[191609] = { ["name"] = "Book of Deathstones: Fungal Spore Cluster", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a fungal spore cluster.\"" }
entries[191610] = { ["name"] = "Book of Deathstones: Ritual Dagger", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a ritual dagger.\"" }
entries[191611] = { ["name"] = "Book of Deathstones: Failsafe Phylactery", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a failsafe phylactery.\"" }
entries[191612] = { ["name"] = "Book of Deathstones: Rune of Teleportation II", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a rune of teleportation.\"" }
entries[191613] = { ["name"] = "Book of Deathstones: Rune of Fortune", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a rune of fortune.\"" }
entries[191614] = { ["name"] = "Book of Deathstones: Skeletal Hitching Post", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a skeletal hitching post.\"" }
entries[191656] = { ["name"] = "Death's Essence", ["text"] = "Binds when picked up\n<Right Click to Open>" }
entries[191660] = { ["name"] = "Thaddius' Lightning Bolts", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Affix the bolts to your neck, applying a positive or negative charge at random that grants 1% increased damage and healing.\n\nThis effect stacks while near allies who have a similar charge, and deals Nature damage to allies who have an opposite charge." }
entries[191661] = { ["name"] = "Monstrous Spider Fang", ["text"] = "Binds when picked up\nDuration: 7 days\nUse: Pierce yourself with the fang, increasing movement speed, attack speed, and cast speed by 15% for 1 hour. (Proc chance: 5%, 30s cooldown)" }
entries[191664] = { ["name"] = "Book of Deathstones: Thaddius' Lightning Bolts", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into Thaddius' lightning bolts.\"" }
entries[191666] = { ["name"] = "Book of Deathstones: Monstrous Spider Fang", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires Level 60\n\"A tome detailing the art of converting deathstones into a monstrous spider fang.\"" }
entries[202251] = { ["name"] = "Bag of Pet Treats", ["text"] = "Binds when picked up\nUse: Open the bag of treats and palm it into your target's pocket, increasing the damage of Beasts against this target by 20. (1 Min Cooldown)\nSell Price:" }
entries[202256] = { ["name"] = "Privateer's Ornate Pistol", ["text"] = "Binds when picked up\nRanged Gun\n6 - 13 Damage Speed 1.90\n(5.00 damage per second)\nDurability 35 / 35\nClasses: Rogue\nEquip: Gain the Quick Draw ability:\n\nDraw your ranged weapon and fire a quick shot at an enemy, causing normal ranged weapon damage and reducing the target's movement speed by 50% for 6 sec. Awards 1 combo point.\n\nQuick Draw benefits from all talents and effects that trigger from or modify Sinister Strike.\nSell Price:" }
entries[202641] = { ["name"] = "Mud-covered notebook", ["text"] = "Binds when picked up\nThis Item Begins a Quest\nClasses: Rogue\n\"This book is covered in mud, but has runes inscribed on its pages, and a short note in a some sort of slang.\"" }
entries[203723] = { ["name"] = "Cutty's Note", ["text"] = "Binds when picked up\nClasses: Rogue\n\"A message written in thieves' cant\"\n<Right Click to Read>" }
entries[203726] = { ["name"] = "Cutty's Rune", ["text"] = "Classes: Rogue" }
entries[203745] = { ["name"] = "Spell Notes: Ice Lance", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nRequires Engraving\n(1)\n\nEngrave your gloves with the Ice Lance rune:\n\nDeals [source value] to [source value] Frost damage to an enemy target. Causes 400% damage against Frozen targets.\n\nWhen your other frost spells deal damage to a non-player controlled target, they increase the target's damage taken from your next Ice Lance by 20%. This effect stacks up to 5 times and requires the Winter's Chill talent.\n\"Teaches you a new Runecarving ability.\"", ["unresolvedValues"] = true }
entries[203746] = { ["name"] = "Spell Notes: Living Flame", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nRequires Engraving\n(1)\n\nEngrave your pants with the Living Flame rune:\n\nSummons a spellfire flame that moves toward the target, leaving a trail of spellfire. This trail deals [source value] Spellfire damage every second to nearby enemies. Lasts 10 sec.\n\"Teaches you a new Runecarving ability.\"", ["unresolvedValues"] = true }
entries[203747] = { ["name"] = "Spell Notes: Fingers of Frost", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nRequires Engraving\n(1)\n\nEngrave your chest or robe with the Fingers of Frost rune:\n\nGives your Chill effects a 25% chance to grant you the Fingers of Frost effect, which treats your next 2 spells cast as if the target were Frozen. Lasts 15 sec.\n\"Teaches you a new Runecarving ability.\"" }
entries[203748] = { ["name"] = "Spell Notes: Burnout", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your chest with the Burnout rune:\n\nIncreases your spell critical strike chance with all spells by 15%, but your non-periodic spell critical strikes now have an additional mana cost of 1% of your base mana.\n\"Teaches you a new Engraving ability.\"" }
entries[203749] = { ["name"] = "Spell Notes: Enlightenment", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your chest or robe with the Enlightenment rune:\n\nYou deal 10% more damage while you have more than 70% mana. While below 30% mana 10% of your mana regeneration continues while casting.\n\"Teaches you a new Engraving ability.\"" }
entries[203750] = { ["name"] = "Elwynn Treasure Map", ["text"] = "Binds when picked up\nClasses: Rogue\nUse: Dig up treasure at the marked location (1 Min Cooldown)\n\"West of ridgepoint tower. Near the stump behind the prowler den.\"" }
entries[203751] = { ["name"] = "Spell Notes: CALE ENCI", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nUse: Decipher the spell notes with a Comphrehension Primer to learn a new Engraving spell." }
entries[203752] = { ["name"] = "Spell Notes: MILEGIN VALF", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nUse: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell." }
entries[203753] = { ["name"] = "Spell Notes: RING SEFF OSTROF", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nUse: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell." }
entries[203754] = { ["name"] = "Archmage Antonidas: The Unabridged Autobiography", ["text"] = "Binds when picked up\nUnique\n\"Somewhat self-indulgent, but nevertheless a fine addition to any library's collection.\"" }
entries[203755] = { ["name"] = "Archmage Theocritus's Research Journal", ["text"] = "Unique\n\"Research notes from the Tower of Azora. A fine addition to any library's collection.\"" }
entries[203756] = { ["name"] = "Azora Apprentice Notes: Page 1", ["text"] = "Binds when picked up\nUnique\nUse: Combine 6 Azora Apprentice Notes to create a new engraving recipe." }
entries[203784] = { ["name"] = "Top-Right Map Piece", ["text"] = "Use: Combine with 3 other pieces to make the full map.\n\"A torn piece of what seems to be a map...\"" }
entries[203785] = { ["name"] = "Top-Left Map Piece", ["text"] = "Use: Combine with 3 other pieces to make the full map.\n\"A torn piece of what seems to be a map...\"" }
entries[203786] = { ["name"] = "Bottom-Right Map Piece", ["text"] = "Use: Combine with 3 other pieces to make the full map.\n\"A torn piece of what seems to be a map...\"" }
entries[203787] = { ["name"] = "Bottom-Left Map Piece", ["text"] = "Use: Combine with 3 other pieces to make the full map.\n\"A torn piece of what seems to be a map...\"" }
entries[203960] = { ["name"] = "Azora Apprentice Notes: Page 2", ["text"] = "Binds when picked up\nUnique\nUse: Combine 6 Azora Apprentice Notes to create a new engraving recipe." }
entries[203961] = { ["name"] = "Azora Apprentice Notes: Page 3", ["text"] = "Binds when picked up\nUnique\nUse: Combine 6 Azora Apprentice Notes to create a new engraving recipe." }
entries[203962] = { ["name"] = "Azora Apprentice Notes: Page 4", ["text"] = "Binds when picked up\nUnique\nUse: Combine 6 Azora Apprentice Notes to create a new engraving recipe." }
entries[203990] = { ["name"] = "Rune of Mutilation", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your gloves with the Mutilate rune:\n\nInstantly attacks with both weapons for 95% weapon damage plus an additional [source value] with each weapon. Damage is increased by 20% against Poisoned targets. Awards 2 combo points.\n\nMutilate benefits from all talents and effects that trigger from or modify Backstab unless otherwise specified.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[203991] = { ["name"] = "Rune of Quick Draw", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your chest or robe with the Quick Draw rune:\n\nDraw your ranged weapon and fire a quick shot at an enemy, causing normal ranged weapon damage and reducing the target's movement speed by 50% for 6 sec. Awards 1 combo point.\n\nQuick Draw benefits from all talents and effects that trigger from or modify Sinister Strike.\n\"Teaches you a new Engraving ability.\"" }
entries[203992] = { ["name"] = "Rune of Trickery", ["text"] = "Classes: Rogue\n\"Teaches you a new Engraving ability.\"" }
entries[203993] = { ["name"] = "Rune of Slaughter", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your chest or robe with the Slaughter from the Shadows rune:\n\nReduces the Energy cost of your Backstab and Ambush abilities by 30, and increases the damage they deal to non-player controlled targets by 70%. [ Engrave Gloves - Mutilate : Does not apply to Mutilate / Does not apply to abilities learned from other runes.]\n\"Teaches you a new Engraving ability.\"" }
entries[203994] = { ["name"] = "Rune of Deadly Brew", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your chest or robe with the Deadly Brew rune:\n\nGrants several improvements to your poisons:\n\nWhen you inflict any other poison on a target, you also inflict Deadly Poison.\n\nIf your weapon does not have a poison applied, it has a chance to trigger Instant Poison as if Instant Poison were applied.\n\nDeadly Poison and Instant Poison now gain increased damage from your Attack Power.\n\nYour Deadly Poison can now be active on targets affected by another Rogue's Deadly Poison.\n\"Teaches you a new Engraving ability.\"" }
entries[204174] = { ["name"] = "Rune of Precision", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your pants with the Between the Eyes rune:\n\nRanged Finishing move that causes damage per combo point, increased by Attack Power, and Stuns the target:\n\n1 point: [source value] to [source value] damage, 1 sec Stun\n2 points: [source value] to [source value] damage, 2 sec Stun\n3 points: [source value] to [source value] damage, 3 sec Stun\n4 points: [source value] to [source value] damage, 4 sec Stun\n5 points: [source value] to [source value] damage, 5 sec Stun\n\nCooldown shared with Kidney Shot.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[204441] = { ["name"] = "Rune of Blood Frenzy", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your chest with the Blood Frenzy rune:\n\nRend can now be used in Berserker stance, Rend's damage is increased by 100%, and Rend deals additional damage equal to 4% of your Attack Power each time it deals damage.\n\"Teaches you a new Engraving ability.\"" }
entries[204476] = { ["name"] = "Severed Kobold Head", ["text"] = "Binds when picked up\nUnique\n\"A grim trophy. May interest the right collector...\"" }
entries[204477] = { ["name"] = "Severed Murloc Head", ["text"] = "Binds when picked up\nUnique\n\"A grim trophy. May interest the right collector...\"" }
entries[204478] = { ["name"] = "Severed Gnoll Head", ["text"] = "Binds when picked up\nUnique\n\"A grim trophy. May interest the right collector...\"" }
entries[204688] = { ["name"] = "Monster Hunter's First Rune Fragment", ["text"] = "Use: Combine with 2 other pieces to make the full rune." }
entries[204689] = { ["name"] = "Monster Hunter's Second Rune Fragment", ["text"] = "Use: Combine with 2 other pieces to make the full rune." }
entries[204690] = { ["name"] = "Monster Hunter's Third Rune Fragment", ["text"] = "Use: Combine with 2 other pieces to make the full rune." }
entries[204703] = { ["name"] = "Rune of Devastate", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your gloves with the Devastate rune:\n\nWhile you are in Defensive Stance and have a shield equipped, Sunder Armor also deals damage equal to 150% of your equipped weapon's damage per second, increased by 15% per application of Sunder Armor already on the target. Devastate damage deals a high amount of threat while you are in Defensive Stance.\n\"Teaches you a new Engraving ability.\"" }
entries[204716] = { ["name"] = "Rune of Frenzied Assault", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your pants with the Frenzied Assault rune:\n\nWhile wielding 2-handed weapons, your attack speed is increased by 40% and your successful melee hits generate 2 additional Rage, or 4 additional Rage if they are critical hits.\n\"Teaches you a new Engraving ability.\"" }
entries[204795] = { ["name"] = "Rune of Shadowstrike", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your gloves with the Shadowstrike rune:\n\nTeleport behind your target and strike, causing 150% weapon damage to the target. Must be stealthed. Awards 1 combo point.\n\"Teaches you a new Engraving ability.\"" }
entries[204806] = { ["name"] = "Rune of Victory Rush", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your gloves with the Victory Rush rune:\n\nInstantly attack the target causing (1 + Attack Power * 45 / 100) damage and healing you for 30% of your maximum health. Only useable within 20 sec after you kill an enemy that yields experience or honor.\n\"Teaches you a new Engraving ability.\"" }
entries[204809] = { ["name"] = "Rune of Furious Thunder", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your pants with the Furious Thunder rune:\n\nThunder Clap now increases the time between attacks by an additional 6%, can be used in any stance, deals 100% increased damage, and deals 75% increased threat.\n\"Teaches you a new Engraving ability.\"" }
entries[204864] = { ["name"] = "Azora Apprentice Notes", ["text"] = "Binds when picked up\nUnique (6)\nUse: Combine 6 Azora Apprentice Notes to create a new engraving recipe." }
entries[204905] = { ["name"] = "Ominous Tome", ["text"] = "Binds when picked up\nUnique\nUse: Summon Soboz\n\"Bring the jaw of a wolf and the blood of a gnoll to the belly of the lamb. Then, begin the incantation.\"" }
entries[204906] = { ["name"] = "Gnoll Blood", ["text"] = "Unique\n\"A reagent for use in a summoning ritual\"" }
entries[204907] = { ["name"] = "Wolf Jawbone", ["text"] = "Unique\n\"A reagent for use in a summoning ritual\"" }
entries[204912] = { ["name"] = "Rune of Grace", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your pants with the Demonic Grace rune:\n\nSurge with fel energy, increasing your pet's and your own dodge chance by 20%, and your chance to critically strike with all attacks by 20%. Lasts 6 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[205019] = { ["name"] = "Tainted Soul Shard", ["text"] = "Binds when picked up\nUnique" }
entries[205020] = { ["name"] = "Pure Soul Shard", ["text"] = "Binds when picked up\nUnique" }
entries[205022] = { ["name"] = "Rune of Soul Siphon", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your cloak with the Soul Siphon rune:\n\nCauses your Drain Soul to to deal damage 3 times faster and increases the amount drained by your Drain Life and Drain Soul spells by an additional 6% for each of your Warlock Shadow effects afflicting the target, up to a maximum of 18% additional effect. When Drain Soul is cast on a target below 20% health, it instead gains 50% per effect, up to a maximum of 150%. In addition, your Drain Soul can now trigger your Nightfall talent.\n\"Teaches you a new Engraving ability.\"" }
entries[205181] = { ["name"] = "Unidentified Artifact", ["text"] = "Binds when picked up\nUnique\n\"Some esoteric magical object. A more experienced Warlock could probably tell you more.\"" }
entries[205182] = { ["name"] = "Powerless Artifact", ["text"] = "Binds when picked up\nUnique\nUse: Offer your blood to power the artifact." }
entries[205183] = { ["name"] = "Fel-Powered Artifact", ["text"] = "Binds when picked up\nUnique" }
entries[205184] = { ["name"] = "Acolyte's Note", ["text"] = "Binds when picked up\nUnique\n<Right Click to Read>" }
entries[205215] = { ["name"] = "Rune of Tactics", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your chest or robe with the Demonic Tactics rune:\n\nIncreases the melee and spell critical strike chance of you and your pet by 10%.\n\"Teaches you a new Engraving ability.\"" }
entries[205218] = { ["name"] = "Libram of Discovery", ["text"] = "Binds when picked up\nUnique\nRelic Libram\nClasses: Paladin\nRequires Level 5\nEngrave your cloak with the Soul Siphon rune:\n\nCauses your Drain Soul to to deal damage 3 times faster and increases the amount drained by your Drain Life and Drain Soul spells by an additional 6% for each of your Warlock Shadow effects afflicting the target, up to a maximum of 18% additional effect. When Drain Soul is cast on a target below 20% health, it instead gains 50% per effect, up to a maximum of 150%. In addition, your Drain Soul can now trigger your Nightfall talent.\n\"Achieve a state of Inspiration by slaying 5 foes, then use to learn a new ability.\"" }
entries[205228] = { ["name"] = "Rune of Chaos Bolt", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your gloves with the Chaos Bolt rune:\n\nSends a bolt of chaotic fire at the enemy, dealing [source value] to [source value] Chaos damage. Chaos Bolt always hits, cannot be resisted, and its knowledge causes all your Fire spells to pierce through absorption effects. Chaos Bolt gains a high chance to be resisted when used against monsters 4 or more levels above your level.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[205230] = { ["name"] = "Rune of Haunting", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your gloves with the Haunt rune:\n\nUnleash a ghostly soul on an enemy, dealing [source value] to [source value] damage, and increasing all Shadow damage over time you deal to that target by 40% for 15 sec. When the Haunt ends or is dispelled, you will be healed for all the damage it dealt to your target.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[205364] = { ["name"] = "Acolyte's Knapsack", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\n<Right Click to Open>" }
entries[205420] = { ["name"] = "Libram of Judgement", ["text"] = "Binds when picked up\nUnique\nRelic Libram\nClasses: Paladin\nEngrave your gloves with the Crusader Strike rune:\n\nAn instant strike that causes 75% weapon damage as Holy and regenerates 5% of your maximum mana. The duration of all Judgement effects on the target is refreshed to 30 sec.\n\"Learn a new ability after unleashing 10 seals onto your enemies\"" }
entries[205683] = { ["name"] = "Rune of Rebuke", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your pants with the Rebuke\nrune:\n\nInterrupts spellcasting and prevents any spell in that school from being cast for 3 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[205685] = { ["name"] = "Rune of Aegis", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your chest with the Aegis rune:\n\nIncreases your block value by 30% and modifies your Redoubt talent. Redoubt now also has a 10% chance to trigger from any melee or ranged attack against you, and always triggers when you deal a melee critical strike. In addition, your Reckoning talent gains a 2% chance per talent point to trigger from any melee or ranged attack against you.\n\"Teaches you a new Engraving ability.\"" }
entries[205863] = { ["name"] = "Corrupted Libram", ["text"] = "Classes: Paladin" }
entries[205864] = { ["name"] = "Charred Note", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\n<Right Click to Read>" }
entries[205897] = { ["name"] = "Rune of Divine Light", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your cloak with the Divine Light rune:\n\nHeals a friendly target for [source value] to [source value]. 50% of any excess healing on the target is converted into an absorption shield that lasts 15 sec. Multiple casts of Divine Light do not accumulate this shield.\n\nDivine Light benefits from all talents and effects that trigger from or modify Holy Light.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[205905] = { ["name"] = "Memory of a Devout Champion", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your chest or robe with the Twisted Faith rune:\n\nMind Flay and Mind Blast deal 50% increased damage to targets afflicted with your Shadow Word: Pain.\n\nUse: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth." }
entries[205932] = { ["name"] = "Prophecy of a King's Demise", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your gloves with the Shadow Word: Death rune:\n\nA word of dark binding that inflicts [source value] to [source value] Shadow damage to the target. If the target is not killed by Shadow Word: Death, the caster takes damage equal to 50% of the damage attempted against the target.\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth.", ["unresolvedValues"] = true }
entries[205940] = { ["name"] = "Memory of a Dark Purpose", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your boots with the Void Plague rune:\n\nAfflicts the target with a disease that causes [source value] Shadow damage over 18 sec.\n\nUse: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth.", ["unresolvedValues"] = true }
entries[205942] = { ["name"] = "Chimaeric Epiphany", ["text"] = "Engrave your pants with the Prayer of Mending rune:\n\nPlaces a spell on the target that heals them for [source value] the next time they take damage or receive healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time.", ["unresolvedValues"] = true }
entries[205943] = { ["name"] = "Prophecy of a Desecrated Citadel", ["text"] = "Unique\nEngrave your pants with the Homunculi rune:\n\nBreak off splinters of your soul to animate 3 miniature copies of yourself that attempt to attack your current target with a mace, sword, and axe, reducing the attack speed, attack power, and armor respectively of any target they hit.\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth." }
entries[205944] = { ["name"] = "Reciprocal Epiphany", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your pants with the Prayer of Mending rune:\n\nPlaces a spell on the target that heals them for [source value] the next time they take damage or receive healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time.\n\"Learn a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[205945] = { ["name"] = "Memory of an Imprisoned Savior", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your pants with the Shared Pain rune:\n\nYour Shadow Word: Pain now also afflicts up to 2 additional nearby targets within 15 yards.\n\nUse: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth." }
entries[205946] = { ["name"] = "Memory of a Leader's Betrayal", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your boots with the Pain Suppression rune:\n\nInstantly reduces all damage taken by a friendly target by 40% and increases resistance to Dispel mechanics by 65% for 8 sec.\n\nUse: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth." }
entries[205947] = { ["name"] = "Prophecy of a Desecrated Citadel", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your pants with the Homunculi rune:\n\nBreak off splinters of your soul to animate 3 miniature copies of yourself that attempt to attack your current target with a mace, sword, and axe, reducing the attack speed, attack power, and armor respectively of any target they hit.\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth." }
entries[205948] = { ["name"] = "Anodyne Epiphany", ["text"] = "Engrave your cloak with the Vampiric Touch rune:\n\nApplies your Vampiric Embrace talent to your target, causes [source value] Shadow damage over 15 sec to your target, and causes all party members to gain mana equal to 2% of any Shadow spell damage you deal to the target.", ["unresolvedValues"] = true }
entries[205949] = { ["name"] = "Manifold Epiphany", ["text"] = "Classes: Priest\nEngrave your gloves with the Circle of Healing rune:\n\nHeals all of target player's party members within 43.5 yards of target player for [source value] to [source value].\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[205950] = { ["name"] = "Tenebrous Epiphany", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your gloves with the Mind Sear rune:\n\nCauses an explosion of shadow magic damaging the enemy target and other nearby enemies, causing [source value] to [source value] Shadow damage every 1 sec for 6 sec to all enemies within 10 yards of the target.\n\"Learn a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[205951] = { ["name"] = "Memory of a Troubled Acolyte", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your gloves with the Penance rune:\n\nLaunches a volley of holy light at the target, causing [source value] Holy damage to an enemy, or [source value] healing to an ally, instantly and every 1 sec for 2 sec.\n\nUse: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth.", ["unresolvedValues"] = true }
entries[205952] = { ["name"] = "Memory of a Shattered World", ["text"] = "Use: Focus on the Memory to learn a new spell. Requires a mind cleared by meditating on the spiritual mysteries of Azeroth." }
entries[205953] = { ["name"] = "Prophecy of a Broken Vow", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your belt with the Mind Spike rune:\n\nBlasts the target for [source value] to [source value] Shadowfrost damage, and increases the critical strike chance of your next Mind Blast on the target by 30%, stacking up to 3 times.\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth.", ["unresolvedValues"] = true }
entries[205961] = { ["name"] = "Mulgore Bird Meat", ["text"] = "Unique\nUse: Place as bait near a mountain cat's dwelling." }
entries[205979] = { ["name"] = "Rune of Flanking", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your pants with the Flanking Strike rune:\n\nYou and your pet deal simultaneous instant 100% melee damage. Afterward, you deal 8% increased damage for 10 sec, stacking up to 3 times. Your pet's Basic attacks have a 50% chance to reset the cooldown on Flanking Strike.\n\"Teaches you a new Engraving ability.\"" }
entries[205995] = { ["name"] = "Prairie Dog Musk", ["text"] = "Classes: Hunter\nUse: Your Tame Beast ability also works on prairie dogs (as companion pet) (10 Min Cooldown)" }
entries[206032] = { ["name"] = "Rune of Carve", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your gloves with the Carve rune:\n\nA sweeping attack that strikes all enemies in front of you with your melee weapons for 65% weapon damage. Your primary target takes 50% increased damage.\n\"Teaches you a new Engraving ability.\"" }
entries[206155] = { ["name"] = "Rune of Marksmanship", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your chest or robe with the Master Marksman rune:\n\nIncreases your critical strike chance by 5%, and reduces the Mana cost of all your Shot abilities by 25%.\n\"Teaches you a new Engraving ability.\"" }
entries[206157] = { ["name"] = "Seaforium Mining Charge", ["text"] = "Quest Item\nUnique (5)" }
entries[206159] = { ["name"] = "Venture Co Disguise", ["text"] = "Quest Item\n\"It doesn't seem like much of a disguise...\"" }
entries[206168] = { ["name"] = "Rune of the Chimera", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your gloves with the Chimera Shot rune:\n\nYou deal 135% weapon damage, refreshing the current Sting on your target and triggering an effect:\n\nSerpent Sting - Instantly deals 48% of the damage done by your Serpent Sting.\n\nViper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.\n\nScorpid Sting - Attempts to Disarm the target for 10 sec. This effect cannot occur more than once per 1 minute.\n\"Teaches you a new Engraving ability.\"" }
entries[206169] = { ["name"] = "Rune of Explosive Shot", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your gloves with the Explosive Shot rune:\n\nYou fire an explosive charge into the enemy target, dealing [Ranged Attack Power * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]-[Ranged Attack Power * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)] Fire damage to all enemies within 8 yards. The charge will deal damage again every second for an additional 2 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[206170] = { ["name"] = "Windfury Cone", ["text"] = "Quest Item" }
entries[206175] = { ["name"] = "Pine Salve", ["text"] = "Quest Item\nUnique" }
entries[206176] = { ["name"] = "Mortar and Pestle", ["text"] = "Quest Item\nUnique\nUse: Grind 8 Windfury Cones together to create a venomous weapon salve. In theory." }
entries[206177] = { ["name"] = "Pine Nut Butter", ["text"] = "Binds when picked up\nUse: Restores 61.2 health over 18 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 2 Stamina and Spirit for 15 min.\nSell Price:" }
entries[206264] = { ["name"] = "Rune of Inspiration", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your pants with the Inspiration Exemplar rune:\n\nYour inspiring presence periodically dispels Fear and Sleep effects on nearby party members.\n\"Teaches you a new Engraving ability.\"" }
entries[206344] = { ["name"] = "Knife Set", ["text"] = "Quest Item\nUnique\nUse: Attempt to fillet a Raw Brilliant Smallfish." }
entries[206345] = { ["name"] = "Fish Chunks", ["text"] = "Quest Item\nUnique" }
entries[206376] = { ["name"] = "Bulwark Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nRequires Level 3\nEngrave your chest or robe with the Shield Mastery rune:\n\nEach time you Block, you regenerate mana equal to 8% of your maximum mana and you gain Armor equal to 30% of your shield's armor value, stacking up to 5 times. You also always gain 10% increased chance to Block and 15% increased Block value.\n\nIn addition, each time you use a Shock ability, you gain 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec.\n\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\"" }
entries[206381] = { ["name"] = "Dyadic Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nEngrave your chest or robe with the Overload rune:\n\nGives your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells a 60% chance to cast a second, similar spell on the same target at no additional cost that causes half damage or healing and no threat.\n\"Learn a new ability after receiving Nature damage 10 times.\"" }
entries[206382] = { ["name"] = "Tempest Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nEngrave your gloves with the Water Shield rune:\n\nThe caster is surrounded by 3 globes of water, granting 1% of your maximum mana per 5 sec. When a spell, melee or ranged attack hits the caster, 4% of maximum mana is restored to the caster. This expends one water globe. Only one globe will activate every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time.\n\"Learn a new ability after hitting 10 non-player enemies with 3 different elements (Nature, Frost, Fire).\"" }
entries[206383] = { ["name"] = "Lithic Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nRequires Level 3\nEngrave your pants with the Earth Shield rune:\n\nProtects the target with an earthen shield, reducing casting or channeling time lost when damaged by 30% and causing attacks to heal the shielded target for [source value]. This effect can only occur once every few seconds. 9 charges. Lasts 10 min. Earth Shield can only be placed on one target at a time.\n\"Learn a new ability after blocking 20 attacks with your shield.\"", ["unresolvedValues"] = true }
entries[206384] = { ["name"] = "Astral Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nRequires Level 3\n\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\"" }
entries[206385] = { ["name"] = "Clastic Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nRequires Level 3\nEngrave your pants with the Way of Earth rune:\n\nWhile Rockbiter Weapon is active on your main hand weapon and you have a shield equipped, you deal 65% increased threat, gain 25% increased health, take 10% reduced damage, gain 6% reduced chance to be critically hit by melee attacks, and Earth Shock taunts targets to attack you and has a separate cooldown from other Shock spells but has its range reduced to melee range. However, the range of your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells is reduced by 20 yards.\n\"Learn a new ability after defeating 20 enemies with Earth Shock.\"" }
entries[206386] = { ["name"] = "Galvanic Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nEngrave your chest or robe with the Shield Mastery rune:\n\nEach time you Block, you regenerate mana equal to 8% of your maximum mana and you gain Armor equal to 30% of your shield's armor value, stacking up to 5 times. You also always gain 10% increased chance to Block and 15% increased Block value.\n\nIn addition, each time you use a Shock ability, you gain 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec.\n\"Learn a new ability after defeating enemies 10 times with Lightning Bolt.\"" }
entries[206387] = { ["name"] = "Kajaric Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nEngrave your gloves with the Lava Burst rune:\n\nYou hurl molten lava at the target, dealing [source value] to [source value] Fire damage. If your Flame Shock is on the target, Lava Burst will deal a critical strike.\n\"Learn a new ability after taking damage from lava 5 times. (Reduces damage from some sources of lava)\"", ["unresolvedValues"] = true }
entries[206388] = { ["name"] = "Sulfurous Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nEngrave your gloves with the Molten Blast rune:\n\nBlast up to 10 enemies in a cone in front of you for [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * Attack Power] to [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * Attack Power] Fire damage. This ability generates a high amount of threat. Flame Shock periodic damage has a 10% chance to reset the cooldown on Molten Blast.\n\"Learn a new ability after defeating 10 enemies with Earth Shock.\"" }
entries[206389] = { ["name"] = "Brimstone Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nRequires Level 3\nEngrave your belt with the Fire Nova rune:\n\nYour Fire Nova Totem spell is replaced with Fire Nova, which causes your current Fire totem to emit damage at its location.\n\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\"" }
entries[206390] = { ["name"] = "Ichthyan Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nRequires Level 3\nEngrave your gloves with the Water Shield rune:\n\nThe caster is surrounded by 3 globes of water, granting 1% of your maximum mana per 5 sec. When a spell, melee or ranged attack hits the caster, 4% of maximum mana is restored to the caster. This expends one water globe. Only one globe will activate every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time.\n\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\"" }
entries[206391] = { ["name"] = "Syzygic Icon", ["text"] = "Binds when picked up\nUnique\nRelic Totem\nClasses: Shaman\nRequires Level 3\nEngrave your bracers with the Riptide\nrune:\n\nHeals a friendly target for [source value] to [source value] and another [source value] over 15 sec. Your Chain Heals cast on that primary target within 15 sec will increase the amount of the Chain Heal by 25%. This spell also triggers Ancestral Awakening.\n\"Learn a new ability after hitting enemies 25 times with Rockbiter Weapon.\"", ["unresolvedValues"] = true }
entries[206466] = { ["name"] = "Prairie Crown", ["text"] = "Use: Awaken a spirit of the plains" }
entries[206469] = { ["name"] = "Prairie Flower", ["text"] = "Classes: Druid\nUse: Combine 3 Prairie Flowers to make a crown." }
entries[206954] = { ["name"] = "Idol of Ursine Rage", ["text"] = "Binds when picked up\nUnique\nRelic Idol\nClasses: Druid\nEngrave your gloves with the Mangle rune:\n\nMangle the target for 160% normal damage and cause the target to take 30% additional damage from Bleed effects and Shred for 1 min. This ability benefits from and triggers all effects associated with Claw and Maul.\n\nHitting a target with Mangle (Bear) also grants you 4 Attack Power for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec.\n\"Learn a new ability after keeping your rage in Bear Form at 50 or higher for 60 seconds\"" }
entries[206963] = { ["name"] = "Rune of Natural Potential", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your chest or robe with the Living Seed rune:\n\nWhen you critically heal your target with any non-periodic healing spell you plant a Living Seed on the target for 50% of the amount healed. The Living Seed will bloom the next time the target takes damage or receives non-periodic healing. Lasts 15 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[206966] = { ["name"] = "Satyrweed Bulb", ["text"] = "Binds when picked up\nUnique\n\"The seedling of an invasive plant species.\"" }
entries[206970] = { ["name"] = "Rune of Life", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your pants with the Lifebloom rune:\n\nReduces the global cooldown on your Rejuvenation and Lifebloom abilities by 0.5 sec and you gain the Lifebloom ability:\n\nHeals the target for [source value] over 7 sec. When Lifebloom completes its duration or is dispelled, the target instantly heals for [source value] and the Druid regains half the cost of the spell. This effect can stack up to 3 times on the same target.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[206975] = { ["name"] = "Artifact Storage Key", ["text"] = "Unique\n\"Opens Artifact Storage chest\"" }
entries[206985] = { ["name"] = "Echo of the Alpha", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nRequires Level 3\n\nEngrave your boots with the Spirit of the Alpha rune:\n\nInfuses the target with the spirit of an alpha wolf, increasing all threat generated by the target by 45% for 30 min. Limit 1 target. If cast on a target other than self, the Shaman also gains Loyal Beta, increasing Physical damage done by 5% and reducing all threat generated by 30% for 30 min. A target cannot have both Spirit of the Alpha and Loyal Beta at the same time.\n\"Learn a new ability.\"" }
entries[206989] = { ["name"] = "Rune of the Sun", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your gloves with the Sunfire rune:\n\nBurns the enemy for [source value] to [source value] Nature damage and then an additional [source value] Nature damage over 12 sec.\n\nIn addition, while in Bear Form, Cat Form, or Dire Bear Form, your Moonfire is replaced with Sunfire (Bear) or Sunfire (Cat). This spell benefits from and triggers all effects associated with Moonfire.\n\nSunfire (Bear)\nBurns the enemy for [source value] to [source value] Nature damage and then an additional [source value] Nature damage over 12 sec.\n\nSunfire (Cat)\nBurns the enemy for [source value] to [source value] Nature damage and then an additional [source value] Nature damage over 12 sec. Awards 1 combo point.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[206992] = { ["name"] = "Rune of Skull Bash", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your gloves with the Skull Bash rune:\n\nCharge to a target within 13 yards and bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for 2 sec. Shares a cooldown with Feral Charge.\n\"Teaches you a new Engraving ability.\"" }
entries[206994] = { ["name"] = "Severed Quilboar Head", ["text"] = "Binds when picked up\nUnique\n\"A grim trophy. May interest the right collector...\"" }
entries[206995] = { ["name"] = "Severed Harpy Head", ["text"] = "Binds when picked up\nUnique\n\"A grim trophy. May interest the right collector...\"" }
entries[207062] = { ["name"] = "Severed Centaur Head", ["text"] = "Binds when picked up\nUnique\n\"A grim trophy. May interest the right collector...\"" }
entries[207098] = { ["name"] = "Note from Ba'so", ["text"] = "Binds when picked up\nClasses: Rogue\n\"A message written in thieves' cant\"\n<Right Click to Read>" }
entries[207106] = { ["name"] = "Bottom-Left Map Piece", ["text"] = "Binds when picked up\nUnique\nUse: Combine with 3 other pieces to make the full map.\n\"A torn piece of what seems to be a map...\"" }
entries[207107] = { ["name"] = "Bottom-Right Map Piece", ["text"] = "Binds when picked up\nUnique\nUse: Combine with 3 other pieces to make the full map.\n\"A torn piece of what seems to be a map...\"" }
