entries[208687] = { ["name"] = "Rune of Lacerate", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your pants with the Lacerate\nrune:\n\nLacerates the enemy target, making them bleed for [source value] damage over 15 sec plus 20% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to 5 times on the same target.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[208689] = { ["name"] = "Ferocious Idol", ["text"] = "Binds when picked up\nUnique\nRelic Idol\nClasses: Druid\nEngrave your pants with the Savage Roar rune:\n\nFinishing move that increases physical damage done by 30% while in Cat Form. Lasts longer per combo point:\n1 point : 14 seconds\n2 points: 19 seconds\n3 points: 24 seconds\n4 points: 29 seconds\n5 points: 34 seconds\n\"Deal 20 instances of bleeding damage to humanoids, then use this idol to learn a new ability.\"" }
entries[208701] = { ["name"] = "Rune of Beast Mastery", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your chest or robe with the Beast Mastery rune:\n\nYour pet's damage and health are increased by 15%, and its Focus regeneration by 50%. In addition, your pet's Growl now also Taunts the target to attack it for 3 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[208739] = { ["name"] = "Horde Warbanner", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\n\"Plant this in the soil of your enemies\"" }
entries[208741] = { ["name"] = "Rune of Endless Rage", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your helm with the Endless Rage rune:\n\nYou generate 25% more Rage from all damage you deal.\n\"Teaches you a new Engraving ability.\"" }
entries[208743] = { ["name"] = "Soul of Greed", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock" }
entries[208744] = { ["name"] = "Rune of Shadowbolts", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your gloves with the Shadow Bolt Volley rune:\n\nYour Shadow Bolt now strikes up to 5 targets within a chain distance of 10 yards, but for 30% reduced damage.\n\"Teaches you a new Engraving ability.\"" }
entries[208749] = { ["name"] = "Gnarlpine Stash Key", ["text"] = "Unique\n\"A tree branch is crudely carved upon the handle.\"" }
entries[208750] = { ["name"] = "Rune of Channeling", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your chest or robe with the Master Channeler rune:\n\nYour Drain Life is no longer channeled, lasts 15 sec with a 15 sec cooldown, costs 100% more mana, and heals you for 50% more each time it deals damage.\n\"Teaches you a new Engraving ability.\"" }
entries[208753] = { ["name"] = "Spell Notes: Regeneration", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your chest or robe with the Regeneration rune:\n\nHeals the target for [source value] health over 3 sec and applies Temporal Beacon for 30 sec.\n\nTemporal Beacon\n\nRecords the subject's space-time position. 70% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[208754] = { ["name"] = "Spell Notes: TENGI RONEERA", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nUse: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell." }
entries[208758] = { ["name"] = "Earthen Rune", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your pants with the Way of Earth rune:\n\nWhile Rockbiter Weapon is active on your main hand weapon and you have a shield equipped, you deal 65% increased threat, gain 25% increased health, take 10% reduced damage, gain 6% reduced chance to be critically hit by melee attacks, and Earth Shock taunts targets to attack you and has a separate cooldown from other Shock spells but has its range reduced to melee range. However, the range of your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells is reduced by 20 yards.\n\"Teaches you a new Engraving ability.\"" }
entries[208760] = { ["name"] = "Glade Crown", ["text"] = "Use: Awaken a spirit of the plains" }
entries[208764] = { ["name"] = "Rune of the Mind", ["text"] = "Unique\nClasses: Priest\nEngrave your belt with the Mind Spike rune:\n\nBlasts the target for [source value] to [source value] Shadowfrost damage, and increases the critical strike chance of your next Mind Blast on the target by 30%, stacking up to 3 times.", ["unresolvedValues"] = true }
entries[208765] = { ["name"] = "Helping Hand", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\n\"The hand will open for a savior\"" }
entries[208766] = { ["name"] = "Helping Hand", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\n\"The hand has opened for you\"\n<Right Click to Open>" }
entries[208767] = { ["name"] = "Rune of Mending", ["text"] = "Unique\nClasses: Priest\nEngrave your pants with the Prayer of Mending rune:\n\nPlaces a spell on the target that heals them for [source value] the next time they take damage or receive healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time.\n\"Teaches you a new Runecarving ability.\"", ["unresolvedValues"] = true }
entries[208768] = { ["name"] = "Buccaneer's Matchbox", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\n\"Used to ignite flammable materials\"" }
entries[208771] = { ["name"] = "Rune of Blade Dance", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your pants with the Blade Dance rune:\n\nFinishing move that increases your Parry chance by 10% and grants 4 Attack Power for each point of your defense skill beyond ( 60 * 5). Lasts longer per combo point:\n\n1 point : 14 seconds\n2 points: 18 seconds\n3 points: 22 seconds\n4 points: 26 seconds\n5 points: 30 seconds\n\"Teaches you a new Engraving ability.\"" }
entries[208772] = { ["name"] = "Rune of Saber Slash", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your gloves with the Saber Slash rune:\n\nViciously slash an enemy for 100% weapon damage, and cause the target to bleed for (Attack Power * 5 / 100) damage every 2 sec for 12 sec, stacking up to 3 times. Each stack also increases damage done by your Saber Slash and Sinister Strike by 50%. Awards 1 combo point.\n\nSaber Slash benefits from all talents and effects that trigger from or modify Sinister Strike.\n\"Teaches you a new Engraving ability.\"" }
entries[208773] = { ["name"] = "Fishing Harpoon", ["text"] = "Binds when picked up\nClasses: Warrior , Hunter\nUse: Throw harpoon at target (40 yd. range)\n\"A must-have for the aspiring shark hunter!\"" }
entries[208777] = { ["name"] = "Rune of the Sniper", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your pants with the Sniper Training rune:\n\nYour Shot abilities gain 2% increased critical strike chance while you have not moved for the last 2 sec, stacking every sec up to 5 times. At 2 or more stacks, your Aimed Shot becomes instant. While moving, you will lose 1 stack per sec.\n\"Teaches you a new Engraving ability.\"" }
entries[208778] = { ["name"] = "Rune of Quick Strike", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your gloves with the Quick Strike rune:\n\nA reckless instant melee attack with your two-handed weapon dealing (Attack Power * 30 / 100) to (Attack Power * 40 / 100) physical damage. This ability benefits from and triggers all effects associated with Heroic Strike.\n\"Teaches you a new Engraving ability.\"" }
entries[208799] = { ["name"] = "Spell Notes: Living Bomb", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your gloves with the Living Bomb rune:\n\nThe target becomes a Living Bomb, taking [source value] Fire damage over 12 sec. After 12 sec or when the spell is dispelled, the target explodes dealing [source value] Fire damage to all enemies within 10 yards.\n\nLiving Bomb benefits from all talents and effects that trigger from or modify Scorch.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
