entries[209852] = { ["name"] = "Rune of Kill Command", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your pants with the Kill Shot rune:\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [source value]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
