entries[210015] = { ["name"] = "Rune of Raging Blow", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your chest with the Raging Blow rune:\n\nA ferocious strike that deals 115% weapon damage, but can only be used while Enrage, Berserker Rage, or Bloodrage is active. Each other melee ability used while Enrage, Berserker Rage, or Bloodrage is active reduces Raging Blow's remaining cooldown by 1 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[210026] = { ["name"] = "Symbol of the Third Owl", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\n\"You have mastered the domain of the sea.\"" }
entries[210043] = { ["name"] = "Symbol of the Second Owl", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\n\"Agon's soul is finally at peace.\"" }
entries[210044] = { ["name"] = "Symbol of the First Owl", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\n\"The mark of a true guardian.\"" }
