entries[210137] = { ["name"] = "Rune of Wild Growth", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your gloves with the Wild Growth rune:\n\nHeals all of target player's party members within 43.5 yards of target player for [source value] over 7 sec. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
