entries[210177] = { ["name"] = "Ataeric: On Arcane Curiosities", ["text"] = "Unique\n\"The writings of a notable Kirin Tor archmage. A fine addition to any library's collection.\"" }
entries[210178] = { ["name"] = "Schematic: Shredder Autosalvage Unit", ["text"] = "Requires Engineering (135)\nSell Price:" }
entries[210179] = { ["name"] = "Spell Notes: ILMEGAI SARRBES", ["text"] = "Binds when picked up\nUnique\nUse: Translate the spell notes into a new runecarving recipe. Requires a reference for the author's shorthand." }
entries[210183] = { ["name"] = "Horn of Xelthos", ["text"] = "Binds when picked up\nUnique\n\"It emits a soft and haunting tone.\"" }
