entries[210188] = { ["name"] = "Shredded Work Order", ["text"] = "Binds when picked up\nUnique\n\"Seems to have been damaged in combat.\"" }
entries[210195] = { ["name"] = "Unbalanced Idol", ["text"] = "Binds when picked up\nUnique\nRelic Idol\nClasses: Druid\nRequires Level 10\nUse: Balance the Powers of the Moon, Emerald Dream, and Wild to learn a new ability." }
entries[210209] = { ["name"] = "Twin Key", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue" }
entries[210210] = { ["name"] = "Grizzwerks Defense Industries Founder's Certificate", ["text"] = "\"The fine print makes it clear this certificate carries no stock value or legal entitlement. If you put your thumb over that part a vendor might buy it.\"\nSell Price:" }
entries[210212] = { ["name"] = "Brother's Half-Key", ["text"] = "Binds when picked up\nUnique\nUse: Combine Brother and Sister Half-Keys." }
entries[210213] = { ["name"] = "Sister's Half-Key", ["text"] = "Binds when picked up\nUnique\nUse: Combine Brother and Sister Half-Keys." }
entries[210229] = { ["name"] = "Rune of Mutilation", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your gloves with the Mutilate rune:\n\nInstantly attacks with both weapons for 95% weapon damage plus an additional [source value] with each weapon. Damage is increased by 20% against Poisoned targets. Awards 2 combo points.\n\nMutilate benefits from all talents and effects that trigger from or modify Backstab unless otherwise specified.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[210250] = { ["name"] = "Engraved Gold Ring", ["text"] = "Binds when picked up\nUnique\nFinger\n\"The engraving reads: While __ both __ kneel __ the __ in __ cemetery.\"" }
entries[210251] = { ["name"] = "Engraved Silver Ring", ["text"] = "Binds when picked up\nUnique\nFinger\n\"The engraving reads: __ wearing __ rings __ before __ statue __ the __\"" }
entries[210252] = { ["name"] = "Rune of Shiving", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your gloves with the Cutthroat rune:\n\nYour Ambush, Backstab, and Garrote abilities no longer require you to be behind your target, and Backstab has a 15% chance to make your next Ambush within 10 sec not require you to be in Stealth.\n\"Teaches you a new Engraving ability.\"" }
entries[210253] = { ["name"] = "Rot Totem", ["text"] = "Binds when picked up\nUnique\nUse: Call to the spirits of the elements.\n\"A traditional totem... twisted and gnarled by dark magic, nearly unrecognizable to those that commune with the elements.\"" }
entries[210322] = { ["name"] = "Rune of Venom", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your pants with the Envenom rune:\n\nFinishing move that deals instant poison damage based on Deadly Poison doses on the target. Following the Envenom attack you have a 75% increased frequency of applying Instant Poison for 1 sec plus an additional 1 sec per combo point. One dose is activated per combo point:\n1 dose: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) + Attack Power * 0.072] damage\n2 doses: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + Attack Power * 0.144] damage\n3 doses: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + Attack Power * 0.216] damage\n4 doses: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + Attack Power * 0.288] damage\n5 doses: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + Attack Power * 0.36] damage\n\"Teaches you a new Engraving ability.\"" }
entries[210323] = { ["name"] = "Safe Combination", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\n\"0-4-5-1\"" }
entries[210329] = { ["name"] = "Hillsbrad Treasure Map", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\n\"Follow the river north; past the Alterac Mountains. What you seek lies beneath the falling rapids.\"" }
entries[210330] = { ["name"] = "Hot Tip", ["text"] = "Binds when picked up\nUnique\n\"Good intel ain't cheap.\"\n<Right Click to Open>" }
entries[210410] = { ["name"] = "Freshwater Snapper Bait", ["text"] = "Classes: Hunter\nUse: Toss bait. (5 Min Cooldown)\n\"Throw some overboard to lure out a big one!\"" }
entries[210499] = { ["name"] = "Marshroom", ["text"] = "Use: Eat (at your own risk)." }
entries[210500] = { ["name"] = "Rune of the Stars", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your pants with the Starsurge rune:\n\nLaunch surging stellar energies that cause [source value] to [source value] Arcane damage, and increases the damage done by your next 1 Starfire cast by 80% for 15 sec.\n\nStarsurge benefits from and triggers most talents and effects that trigger or benefit from Wrath or Starfire.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[210534] = { ["name"] = "Idol of the Wild", ["text"] = "Binds when picked up\nUnique\nRelic Idol\nClasses: Druid\nEngrave your chest or robe with the Wild Strikes rune:\n\nWhile you are in Cat Form, Bear Form, or Dire Bear Form, party or raid members within 100 yards gain increased combat ferocity. Each melee hit has a 20% chance of granting the attacker an extra attack with 20% additional Attack Power. No effect if the target is already benefitting from Windfury Totem.\n\"Heal 10 different beasts, then use this idol to learn a new ability.\"" }
entries[210568] = { ["name"] = "Decrepit Phylactery", ["text"] = "Binds when picked up\nUnique\n\"A heinous aura eminates from the artifact.\"" }
entries[210569] = { ["name"] = "Rune of Flagellation", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your chest with the Flagellation rune:\n\nYou gain Rage from Physical damage taken as if you were wearing no armor.\n\"Teaches you a new Engraving ability.\"" }
entries[210573] = { ["name"] = "Rune of Consuming Rage", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your pants with the Consumed by Rage rune:\n\nEnrages you (activating abilities which require being Enraged) for 12 sec after you exceed 60 Rage. In addition, Whirlwind also strikes with off-hand melee weapons while you are Enraged.\n\"Teaches you a new Engraving ability.\"" }
entries[210589] = { ["name"] = "Echo of the Ancestors", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your pants with the Ancestral Guidance rune:\n\nFor the next 10 sec, 25% of your damage is converted to healing on up to 3 nearby party members, and 100% of your healing is converted to damage on your most recent Flame Shock target.\n\"Learn a new Engraving ability.\"" }
entries[210596] = { ["name"] = "Rune of Cobra Strikes", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your chest or robe with the Cobra Strikes rune:\n\nYour critical hits with Shot and Strike abilities and with Mongoose Bite cause your pet's next 2 special attacks to critically hit.\n\"Teaches you a new Engraving ability.\"" }
entries[210653] = { ["name"] = "Rune of Main Gauche", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your gloves with the Main Gauche rune:\n\nInstantly strike with your off-hand weapon for normal off-hand weapon damage and increase your chance to parry by 100% for 5 sec or until you successfully parry. For 20 sec after using Main Gauche, Sinister Strike costs 20 less Energy, deals 50% more threat, grants stacks of Rolling with the Punches, and both Sinister Strike and Eviscerate deal 50% more damage. Awards 1 combo point.\n\nMain Gauche benefits from most talents and effects that trigger from or modify Sinister Strike. Main Gauche's effect will not discount or empower Main Gauche.\n\"Teaches you a new Engraving ability.\"" }
entries[210654] = { ["name"] = "Spell Notes: Rewind Time", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your bracers with the Rewind Time rune:\n\nYour current target with your Temporal Beacon instantly heals all damage taken over the last 5 seconds. Ineffective on targets that did not have a Temporal Beacon 5 seconds ago.\n\"Teaches you a new Engraving ability.\"" }
entries[210655] = { ["name"] = "Spell Notes: TERWEM DINI", ["text"] = "Binds when picked up\nUnique\nUse: Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell." }
entries[210665] = { ["name"] = "Mote of Torrential Rage", ["text"] = "Binds when picked up\nUnique" }
entries[210667] = { ["name"] = "Mote of Infernal Rage", ["text"] = "Binds when picked up\nUnique" }
entries[210668] = { ["name"] = "Mote of Seismic Rage", ["text"] = "Binds when picked up\nUnique" }
entries[210708] = { ["name"] = "Elixir of Coalesced Regret", ["text"] = "Requires Level 20\n\nUse: Allows the imbiber to speak with the corpse of an individual with unfinished business in the mortal world. Also may cure indigestion. (3 Sec Cooldown)\nSell Price:" }
entries[210709] = { ["name"] = "Recipe: Elixir of Coalesced Regret", ["text"] = "Requires Alchemy (90)\n\nUse: Teaches you how to make an Elixir of Coalesced Regret.\nSell Price:\nElixir of Coalesced Regret\nRequires Level 20\n\nUse: Allows the imbiber to speak with the corpse of an individual with unfinished business in the mortal world. Also may cure indigestion. (3 Sec Cooldown)\nSell Price:\nRequires Stranglekelp (5), Leaded Vial , Grave Moss (5), Soul Dust" }
entries[210712] = { ["name"] = "Elixir of Insight", ["text"] = "Binds when picked up\nUse: Behold a vision at Je'neu's bonfire." }
entries[210713] = { ["name"] = "Tortured Soul", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Make an Offering of Blood to release this Tortured Soul." }
entries[210724] = { ["name"] = "Hirzek's Staff", ["text"] = "Binds when picked up" }
entries[210746] = { ["name"] = "Rune of Earth Shield", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your pants with the Earth Shield rune:\n\nProtects the target with an earthen shield, reducing casting or channeling time lost when damaged by 30% and causing attacks to heal the shielded target for [source value]. This effect can only occur once every few seconds. 9 charges. Lasts 10 min. Earth Shield can only be placed on one target at a time.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[210763] = { ["name"] = "Bough of Altek", ["text"] = "Binds when picked up\nUnique\n\"A splintered fragment of power. It appears this was once half of a great weapon.\"" }
entries[210765] = { ["name"] = "Orb of Des", ["text"] = "Binds when picked up\nUnique\n\"Flames and dark magic swirl through the orb, mesmerizing yet deeply concerning. It appears this was once half of a great weapon.\"" }
entries[210771] = { ["name"] = "Waylaid Supplies: Copper Bars", ["text"] = "Binds when picked up\nUnique: Waylaid Shipment (12)\nUse: Add 20 Copper Bars to complete the shipment.\nSell Price:" }
entries[210772] = { ["name"] = "Supply Shipment: Copper Bars", ["text"] = "Binds when picked up\nUnique: Supply Shipment (1)\n\"Deliver to a supply officer for a substantial reward.\"" }
entries[210779] = { ["name"] = "Plans: Mantle of the Second War", ["text"] = "Binds when picked up\nRequires Blacksmithing (150)\n\nUse: Teaches you how to craft a Mantle of the Second War.\nSell Price:\nMantle of the Second War\nBinds when equipped\nShoulder Mail\n163 Armor\n+8 Stamina\nDurability 70 / 70\nRequires Level 25\nEquip: Increases damage done by Holy spells and effects by up to 11.\nSell Price:\nRequires Bronze Bar (20), Moss Agate (2), Lesser Moonstone (2), Iridescent Pearl (2), Silver Bar (4)" }
entries[210781] = { ["name"] = "Phoenix Bindings", ["text"] = "Binds when equipped\nWrist Cloth\n21 Armor\nDurability 30 / 30\nRequires Level 25\nEquip: Increases damage done by Fire spells and effects by up to 13.\nSell Price:" }
entries[210811] = { ["name"] = "Rune of Primordial Fury", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your pants with the Greater Ghost Wolf rune:\n\nYour Ghost Wolf ability can now be used indoors, and reduces all damage you take by 10% while active.\n\"Teaches you a new Engraving ability.\"" }
entries[210817] = { ["name"] = "Rune of Survival", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your chest or robe with the Survival of the Fittest rune:\n\nReduces the chance you'll be critically hit by melee attacks by 6% and reduces all damage taken by 10%. Damage taken reduced by an additional 10% while in Bear Form or Dire Bear Form.\n\"Teaches you a new Engraving ability.\"" }
entries[210818] = { ["name"] = "Rune of Lone Wolf", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your chest or robe with the Lone Wolf rune:\n\nYou deal 25% increased damage with all attacks while you do not have an active pet.\n\"Teaches you a new Engraving ability.\"" }
entries[210820] = { ["name"] = "Rune of Sacrifice", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your pants with the Hand of Sacrifice rune:\n\nCauses target party or raid member to transfer 30% of damage taken to the caster. Lasts 12 sec or until the caster has transferred 100% of their maximum health.\n\"Teaches you a new Engraving ability.\"" }
entries[210822] = { ["name"] = "Harmonious Epiphany", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your chest or robe with the Serendipity rune:\n\nHealing with Flash Heal reduces the cast time of your next Lesser Heal, Heal, Greater Heal, or Prayer of Healing by 20% for 20 sec, stacking up to 3 times.\n\"Learn a new Engraving ability.\"" }
entries[210823] = { ["name"] = "Rune of Dual Wield Specialization", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your chest or robe with the Dual Wield Specialization rune:\n\nIncreases your chance to hit with both spells and melee attacks by 5% while dual wielding, your Stormstrike ability now hits with both weapons while dual wielding, and increases the damage done by your offhand weapon by 60%.\n\"Teaches you a new Engraving ability.\"" }
entries[210824] = { ["name"] = "Rune of the Pact", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your pants with the Demonic Pact rune:\n\nYour Fire and Shadow spells deal 10% more damage, and your pet's critical strikes apply the Demonic Pact effect to your party or raid members for 45 sec. Demonic Pact increases spell damage and healing by 10% of your spell damage or ( 60 / 2), whichever is higher. Does not work on Subjugated demons.\n\"Teaches you a new Engraving ability.\"" }
entries[210825] = { ["name"] = "Rune of the Warbringer", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your chest with the Warbringer rune:\n\nYour Charge, Intercept, and Intervene abilities are now usable while in combat and in any stance, and will all remove movement impairing effects when activated.\n\"Teaches you a new Engraving ability.\"" }
entries[210953] = { ["name"] = "Eye of Bhossca", ["text"] = "Binds when picked up\nUnique\n\"Though the eye is inanimate, you feel watched...\"" }
entries[210955] = { ["name"] = "Scarlet Initiate's Uniform", ["text"] = "Binds when picked up\nUnique\nUse: Disguise yourself as a member of the Scarlet Crusade. Suspicious activity will break the disguise." }
entries[210963] = { ["name"] = "Scryer's Key", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue" }
entries[210966] = { ["name"] = "Blood of the Legion", ["text"] = "Quest Item\nUnique (10)\n\"Dark and thick... This blood links back to great commanders of the legion.\"" }
entries[210967] = { ["name"] = "Confidential Message", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\n<Right Click to Read>" }
entries[210968] = { ["name"] = "Reliquary Key", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue" }
entries[210979] = { ["name"] = "Rune of Shadowstep", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your belt with the Shadowstep rune:\n\nAttempts to step through the shadows and reappear behind your enemy and increases movement speed by 70% for 3 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[210980] = { ["name"] = "Rune of Metamorphosis", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your gloves with the Metamorphosis rune:\n\nTransform into a Demon, increasing Armor by 500%, Health by 15%, reducing the chance you will be critically hit by 6%, increasing your threat by 50%, increasing mana gained from Life Tap by 100%, but reducing all damage you deal by 10%. Metamorphosis transforms the functionality of some abilities and grants new ones:\n\nSearing Pain: Now instant.\n\nShadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to 10 nearby enemies, but has a 6 sec cooldown.\n\nFear: Replaced with Menace.\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\nDemon Charge\n\nCharge an enemy and stun it for 1 sec. Cannot be used in combat.\n\nDemonic Howl\n\nForces all nearby enemies to focus attacks on you for 6 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[211205] = { ["name"] = "Rune of Cobra Slayer", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your gloves with the Cobra Slayer rune:\n\nMongoose Bite now has a 10% chance to activate on each of your melee attacks, a 100% chance when an enemy dodges. This chance accumulates, with the chance rising by 10% from each subsequent attack if it does not reset. Mongoose Bite also deals additional damage equal to 45% of your Attack Power.\n\"Teaches you a new Engraving ability.\"" }
entries[211247] = { ["name"] = "Pattern: Phoenix Bindings", ["text"] = "Binds when picked up\nRequires Tailoring (125)\n\nUse: Teaches you how to sew Phoenix Bindings.\nSell Price:\nPhoenix Bindings\nBinds when equipped\nWrist Cloth\n21 Armor\nDurability 30 / 30\nRequires Level 25\nEquip: Increases damage done by Fire spells and effects by up to 13.\nSell Price:\nRequires Bolt of Woolen Cloth (6), Flask of Oil (2), Fine Thread (2)" }
entries[211269] = { ["name"] = "Primitive Drawing", ["text"] = "Binds when picked up\nThis Item Begins a Quest" }
