entries[211385] = { ["name"] = "Rune of Serpent Spread", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your pants with the Serpent Spread rune:\n\nTargets hit by your Multi-Shot are also afflicted by your Serpent Sting for 12 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[211386] = { ["name"] = "Spell Notes: Arcane Surge", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your pants with the Arcane Surge rune:\n\nUnleash all of your remaining mana in a surge of energy focused at the target dealing [source value] to [source value] Arcane damage, increased by up to 300% based on your mana remaining. Afterward, your normal mana regeneration is activated and increased by 300% for 8 sec.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[211387] = { ["name"] = "Rune of Beckoning Light", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your gloves with the Beacon of Light rune:\n\nThe target becomes a Beacon of Light to all members of your party or raid within a 40 yard radius. Any heals you cast on party or raid members will also heal the Beacon for 75% of the amount healed. Only one target can be the Beacon of Light at a time. Lasts 1 hour.\n\"Teaches you a new Engraving ability.\"" }
entries[211390] = { ["name"] = "Rune of Teasing", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your chest or robe with the Just a Flesh Wound rune:\n\nYou take 20% reduced Physical damage while Blade Dance is active, reduced by an additional 1% for every 12 of your Defense skill beyond ( 60 * 5). Additionally, your chance to Dodge is multiplied by 50%, you have 6% reduced chance to be critically hit by melee attacks, you deal 20% less damage, the threat generated by all your actions is massively increased, and your Feint ability is replaced with Tease, which Taunts the target to attack you.\n\nTaunts the target to attack you, but has no effect if the target is already attacking you.\n\"Teaches you a new Engraving ability.\"" }
entries[211391] = { ["name"] = "Rune of Healing Rain", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your chest or robe with the Healing Rain rune:\n\nSelects the area 15 yards around target player, and heals all of target player's party members within that area for [source value] every second.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[211392] = { ["name"] = "Rune of Everlasting Affliction", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your pants with the Everlasting Affliction rune:\n\nDrain Life, Drain Soul, Shadowbolt, Shadow Cleave, Searing Pain, Incinerate, and Haunt refresh the duration of your Corruption on the target back to its maximum duration.\n\"Teaches you a new Engraving ability.\"" }
entries[211393] = { ["name"] = "Rune of Single-Minded Fury", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your gloves with the Single-Minded Fury rune:\n\nWhile dual-wielding, your movement speed is increased by 10% and you gain 4% attack speed each time your melee auto-attack strikes the same target as your previous auto-attack, stacking up to 5 times. Lasts 10 sec or until your auto-attack strikes a different target.\n\"Teaches you a new Engraving ability.\"" }
entries[211419] = { ["name"] = "Handful of Shifting Scales", ["text"] = "Binds when picked up\nUnique\n\"These curious scales seem to shimmer slightly, as if they are not fully corporeal. There is clearly wonderous magic at play here... if only you could find someone who knows more about them.\"" }
entries[211427] = { ["name"] = "Soul Vessel", ["text"] = "\"Traps demon souls and siphons them for power.\"" }
entries[211447] = { ["name"] = "Arms Shipment", ["text"] = "Quest Item\nUnique" }
entries[211448] = { ["name"] = "Signed Procurement Contract", ["text"] = "Quest Item\nUnique" }
entries[211471] = { ["name"] = "Cliffspring Key", ["text"] = "Unique" }
entries[211472] = { ["name"] = "Libram of Banishment", ["text"] = "Binds when picked up\nUnique\nRelic Libram\nClasses: Paladin\nEngrave your pants with the Aura Mastery rune:\n\nCauses your Concentration Aura to make all affected targets immune to Silence and Interrupt effects and improves the effect of all other auras by 100%. Lasts 6 sec.\n\"Learn a new ability after casting Turn Undead on 5 enemies, and slaying them with Exorcism.\"" }
entries[211476] = { ["name"] = "Rune of Fires Wake", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your chest or robe with the Lake of Fire rune:\n\nYour Rain of Fire is no longer channeled, but gains a 8 sec cooldown.\n\"Teaches you a new Engraving ability.\"" }
entries[211477] = { ["name"] = "Rune of Incinerate", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your bracers with the Incinerate rune:\n\nBurn your enemy for [source value] to [source value] damage and increase all Fire damage you deal by 40% for the next 15 sec.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[211482] = { ["name"] = "Shatterspear Offering", ["text"] = "Binds when picked up\nUnique" }
entries[211487] = { ["name"] = "Demolition Explosives", ["text"] = "Binds when picked up\nUnique\nUse: Place a bomb with a short fuse on the ground in front of you.\n\"Only seems useful for clearing out debris and rubble.\"" }
entries[211488] = { ["name"] = "Rune of the Avenger", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your pants with the Avenger's Shield rune:\n\nHurls a holy shield at the enemy, dealing [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell Power + 0.091 * Attack Power] to [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * Spell Power + 0.091 * Attack Power] Holy damage, Dazing them and then jumping to additional nearby enemies. Affects 3 total targets. Lasts 5 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[211490] = { ["name"] = "Prophecy of a Thousand Lights", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your gloves with the Circle of Healing rune:\n\nHeals all of target player's party members within 43.5 yards of target player for [source value] to [source value].\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth.\n\"Learn a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[211498] = { ["name"] = "Trainee's Sentinel Nightsaber", ["text"] = "Binds when picked up\nMount\nRequires any Alliance race\nRequires Level 25\n\nUse: Summons a Trainee's Sentinel Nightsaber. Only usable in Ashenvale. (3 Sec Cooldown)" }
entries[211499] = { ["name"] = "Trainee's Outrider Wolf", ["text"] = "Binds when picked up\nMount\nRequires any Horde race\nRequires Level 25\n\nUse: Summons a Trainee's Outrider Wolf. Only usable in Ashenvale. (3 Sec Cooldown)" }
entries[211500] = { ["name"] = "Resilient Cloth Headband", ["text"] = "Binds when picked up\nUnique\nHead Cloth\n50 Armor\nDurability 50 / 50\nRequires Level 20\nEquip: Reduces all damage taken and chance to be critically hit by 5% in Warsong Gulch." }
entries[211514] = { ["name"] = "Spell Notes: Mass Regeneration", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your pants with the Mass Regeneration rune:\n\nHeals all of target player's party members within 43.5 yards of target player for [source value] health over 3 sec and applies Temporal Beacon to each target for 15 sec.\n\nTemporal Beacon\n\nRecords the subject's space-time position. 70% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[211527] = { ["name"] = "Cozy Sleeping Bag", ["text"] = "Binds when picked up\nUnique\nUse: Unfurl a sleeping bag. Resting inside for at least one minute will provide a bonus to experience earned, stacking up to 3 times. (1 Hour Cooldown)\n\"Old, but still good\"\nSell Price:" }
entries[211528] = { ["name"] = "Dark Insight", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nUse: Consider at a certain secluded grave in Duskwood to receive a prophecy." }
entries[211530] = { ["name"] = "Prophecy of a City Enthralled", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your bracers with the Power Word: Barrier rune:\n\nSummons a holy barrier to protect all party members at the target location for 10 sec, reducing all damage taken by 25% and preventing damage from delaying spellcasting.\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth." }
entries[211531] = { ["name"] = "Prophecy of Seven Visitors", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your chest or robe with the Strength of Soul rune:\n\nLesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal.\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth." }
entries[211534] = { ["name"] = "Primal Insight", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nUse: Consider at a Thistlefur dreamcatcher high in the canopy to receive a prophecy." }
entries[211691] = { ["name"] = "Spell Notes: Arcane Blast", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your gloves with the Arcane Blast rune:\n\nBlasts the target with energy, dealing [source value] to [source value] Arcane damage. Each time you cast Arcane Blast, the damage of all other Arcane spells is increased by 15% and mana cost of Arcane Blast is increased by 175%. Effect stacks up to 4 times and lasts 6 sec or until any other Arcane damage spell is cast.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
